package com.moishow.identity;
import org.springframework.context.annotation.Profile;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
import java.util.*;import static com.moishow.identity.ApiProblem.require;
@Service @Profile("db")
class CommunityGroups {
 final CommunityService c;final Store db;final org.springframework.jdbc.core.JdbcTemplate sql;CommunityGroups(CommunityService c,Store db,org.springframework.jdbc.core.JdbcTemplate sql){this.c=c;this.db=db;this.sql=sql;}
 void group(Map<String,Object> room){require(room.get("kind").equals("GROUP_DM"),400,"GROUP_ROOM_REQUIRED");}
 void safeInvite(UUID room,UUID candidate){require(db.find(Models.Account.class,candidate).status.equals("ACTIVE"),400,"USER_UNAVAILABLE");for(var peer:sql.queryForList("select user_id from community_room_member where room_id=? and status='ACTIVE'",UUID.class,room))require(!c.blocked(peer,candidate),403,"INVITATION_UNAVAILABLE");}
 void invite(Actor a,UUID id,List<UUID> users){require(users!=null&&!users.isEmpty()&&users.stream().noneMatch(Objects::isNull),400,"INVITEES_REQUIRED");for(UUID user:new LinkedHashSet<>(users)){require(!user.equals(a.userId()),400,"CANNOT_INVITE_SELF");safeInvite(id,user);var current=sql.queryForList("select status from community_room_member where room_id=? and user_id=?",id,user);require(current.isEmpty()||!current.getFirst().get("status").equals("ACTIVE"),409,"ALREADY_MEMBER");sql.update("insert into community_room_member(room_id,user_id,status,inviter_id) values(?,?,'INVITED',?) on conflict(room_id,user_id) do update set status='INVITED',inviter_id=excluded.inviter_id,joined_at=null,left_at=null",id,user,a.userId());c.socialNotice(a,user,"chat:group-invite:"+id,"그룹 대화 초대가 도착했어요.");}}
 public Object create(Actor a,CommunityController.GroupForm b){c.social(a);String title=ClubService.text(b.title(),100);UUID id=UUID.randomUUID();sql.update("insert into community_room(id,kind,title,status,requester_id) values(?,'GROUP_DM',?,'ACTIVE',?)",id,title,a.userId());sql.update("insert into community_room_member(room_id,user_id,status,inviter_id,joined_at) values(?,?,'ACTIVE',?,now())",id,a.userId(),a.userId());invite(a,id,b.userIds());return c.roomView(a,c.room(id,false));}
 public Object invite(Actor a,UUID id,CommunityController.InviteForm b){c.social(a);var r=c.room(id,true);group(r);require(c.roomAccess(a,r,true),403,"ROOM_ACCESS_DENIED");invite(a,id,b.userIds());return c.roomView(a,r);}
 @Transactional(readOnly=true) public Object invitations(Actor a,int offset,int limit){return CommunityService.page(sql.queryForList("select r.*,m.inviter_id from community_room r join community_room_member m on m.room_id=r.id where m.user_id=? and m.status='INVITED' order by r.created_at desc,r.id",a.userId()).stream().filter(r->sql.queryForList("select user_id from community_room_member where room_id=? and status='ACTIVE'",UUID.class,r.get("id")).stream().noneMatch(peer->c.blocked(peer,a.userId()))).map(r->{var v=c.roomView(a,r);v.put("lastMessage","");v.put("lastMessageAt",null);v.put("memberStatus","INVITED");v.put("inviterId",r.get("inviter_id"));v.put("inviterNickname",c.nickname((UUID)r.get("inviter_id"),null));return v;}).toList(),offset,limit);}
 public Object decide(Actor a,UUID id,boolean decline){if(!decline)c.social(a);var r=c.room(id,true);group(r);require(c.exists("select exists(select 1 from community_room_member where room_id=? and user_id=? and status='INVITED')",id,a.userId()),403,"INVITEE_REQUIRED");if(!decline)safeInvite(id,a.userId());long minimum=decline?0:sql.queryForObject("select coalesce(max(sequence),0)+1 from community_message where room_id=?",Long.class,id);sql.update("update community_room_member set status=?,min_sequence=?,joined_at=case when ? then now() else null end where room_id=? and user_id=?",decline?"DECLINED":"ACTIVE",minimum,!decline,id,a.userId());return Map.of("id",id,"status",decline?"DECLINED":"ACTIVE");}
 public Object leave(Actor a,UUID id){var r=c.room(id,true);group(r);require(c.roomAccess(a,r,true),403,"ROOM_ACCESS_DENIED");sql.update("update community_room_member set status='LEFT',left_at=now() where room_id=? and user_id=?",id,a.userId());return Map.of("id",id,"status","LEFT");}
 @Transactional(readOnly=true) public Object members(Actor a,UUID id,int offset,int limit){var r=c.room(id,false);require(c.roomAccess(a,r,true),403,"ROOM_ACCESS_DENIED");String kind=(String)r.get("kind");var result=new ArrayList<Map<String,Object>>();if(kind.equals("GROUP_DM")){for(var m:sql.queryForList("select user_id,status,inviter_id from community_room_member where room_id=? and status in ('ACTIVE','INVITED') order by joined_at nulls last,user_id",id)){var v=CommunityService.view(m);v.put("nickname",c.nickname((UUID)m.get("user_id"),null));result.add(v);}}else if(kind.equals("DIRECT")){for(String key:List.of("user_a","user_b")){UUID user=(UUID)r.get(key);result.add(Map.of("userId",user,"nickname",c.nickname(user,null),"status","ACTIVE"));}}else if(kind.equals("CLUB")){for(var m:db.list(Models.Membership.class,"from Membership where clubId=?1 and status='ACTIVE' and blacklisted=false order by userId",r.get("club_id")))result.add(Map.of("userId",m.userId,"nickname",c.nickname(m.userId,m.clubId),"status",m.status));}else{var e=db.find(Models.ClubEvent.class,(UUID)r.get("event_id"));var users=new LinkedHashSet<UUID>();users.add(e.hostId);users.addAll(sql.queryForList("select distinct p.user_id from participation p join event_round er on er.id=p.round_id where er.event_id=? and p.ever_confirmed",UUID.class,e.id));for(UUID user:users)result.add(Map.of("userId",user,"nickname",c.nickname(user,e.clubId),"status","PARTICIPANT"));}return CommunityService.page(result,offset,limit);}
}
